"""
Translate the provided C MPI code into a parallel Python implementation using the PyCOMPSs framework.

Task Specifications:
- Paradigm & Language Shift: Completely remove the SPMD execution model and explicit MPI communications (`MPI_Scatterv`, `MPI_Gatherv`, etc.). Translate the C memory management (pointers, `malloc`) and arrays into standard Python lists or NumPy arrays.
- Parallelization Strategy: Convert the `compute_relu` logic into a main(x) function that calls the necessary `@task` decorated Python function.
- Data Directionality: Explicitly define the direction of the parameters (e.g., `IN`, `OUT`, `INOUT` or `RETURNS`) inside the `@task` decorator so PyCOMPSs can automatically build the dependency graph.
- Orchestration: Create a Python `main(x)` function that acts as the master node. It should chunk the data natively in Python, dispatch the `@task` functions asynchronously over those chunks, and reconstruct the final array.
- Synchronization: Explicitly synchronize the scattered task futures back into actual values using `compss_wait_on` before printing the final result.
- Complexity Analysis: Include a brief breakdown of the expected time and space complexity of the generated PyCOMPSs Python code.

C MPI Code to Translate:
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>

void compute_relu(float* local_data, int local_size) {
    for (int i = 0; i < local_size; i++) {
        if (local_data[i] < 0.0f) {
            local_data[i] = 0.0f;
        }
    }
}

int main(int argc, char** argv) {
    MPI_Init(&argc, &argv);

    int rank, size;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    int total_elements = 7;
    float* global_data = NULL;
    int* sendcounts = malloc(size * sizeof(int));
    int* displs = malloc(size * sizeof(int));

    if (rank == 0) {
        global_data = (float*)malloc(total_elements * sizeof(float));
        float initial_data[] = {-1.8f, 24.0f, 1.2f, 0.0f, -5.1f, -0.2f, 4.5f};
        for (int i = 0; i < total_elements; i++) {
            global_data[i] = initial_data[i];
        }

        int remainder = total_elements % size;
        int offset = 0;
        for (int i = 0; i < size; i++) {
            sendcounts[i] = total_elements / size + (i < remainder ? 1 : 0);
            displs[i] = offset;
            offset += sendcounts[i];
        }
    }

    int local_size;
    MPI_Scatter(sendcounts, 1, MPI_INT, &local_size, 1, MPI_INT, 0, MPI_COMM_WORLD);

    float* local_data = (float*)malloc(local_size * sizeof(float));
    MPI_Scatterv(global_data, sendcounts, displs, MPI_FLOAT, 
                 local_data, local_size, MPI_FLOAT, 0, MPI_COMM_WORLD);

    compute_relu(local_data, local_size);

    MPI_Gatherv(local_data, local_size, MPI_FLOAT, 
                global_data, sendcounts, displs, MPI_FLOAT, 0, MPI_COMM_WORLD);

    if (rank == 0) {
        printf("Rank 0 | Final ReLU Output: ");
        for (int i = 0; i < total_elements; i++) {
            printf("%.1f ", global_data[i]);
        }
        printf("\n");
        free(global_data);
    }

    free(local_data);
    free(sendcounts);
    free(displs);

    MPI_Finalize();
    return 0;
}

